enum MethodType {
    case safe
    case idempotent
    case nonIdempotent
}
func classify(verb: String) -> MethodType {
    switch verb {
    case "GET", "HEAD":
        return .safe
    case "PUT", "DELETE":
        return .idempotent
    default:
        return .nonIdempotent
    }
}
let kind = classify(verb: "GET")
print("GET kind: \(kind == .safe)")

func isClientError(code: Int) -> Bool {
    return code >= 400 && code < 500
}
print("Is 404 client error: \(isClientError(code: 404))")

struct Endpoint {
    let path: String
    var isRESTCompliant: Bool {
        !path.contains("get") && !path.contains("delete")
    }
}
let ep = Endpoint(path: "/api/v1/users/42")
print("Compliant: \(ep.isRESTCompliant)")

func isSuccess(code: Int) -> Bool {
    return (200...299).contains(code)
}
print("Success 204: \(isSuccess(code: 204))")

