struct HTTPResponseEvaluator {
    static func isSuccess(statusCode: Int) -> Bool {
        return (200...299).contains(statusCode)
    }
}

let okCheck = HTTPResponseEvaluator.isSuccess(statusCode: 200)
let errCheck = HTTPResponseEvaluator.isSuccess(statusCode: 404)
print("Evaluator check: \(okCheck && !errCheck)")

struct HTTPMethodClassifier {
    func isIdempotent(method: String) -> Bool {
        return method == "GET" || method == "PUT" || method == "DELETE"
    }
}

let classifier = HTTPMethodClassifier()
let getCheck = classifier.isIdempotent(method: "GET")
let postCheck = classifier.isIdempotent(method: "POST")
print("Idempotence check: \(getCheck && !postCheck)")

class StatusCodeRouter {
    func handle(code: Int) -> String {
        switch code {
        case 401: return "refresh_token"
        case 403: return "access_denied"
        case 404: return "not_found"
        default: return "default_handler"
        }
    }
}

let router = StatusCodeRouter()
let res1 = router.handle(code: 401)
let res2 = router.handle(code: 403)
let res3 = router.handle(code: 404)
print("Routes: \(res1), \(res2), \(res3)")
